CREATE OR REPLACE FUNCTION classify_filing_window(submission_date DATE, start_date DATE)
RETURNS TEXT AS $$
DECLARE
    months_diff INTEGER;
BEGIN
    months_diff := (EXTRACT(YEAR FROM start_date) - EXTRACT(YEAR FROM submission_date)) * 12 
                 + EXTRACT(MONTH FROM start_date) - EXTRACT(MONTH FROM submission_date);

    IF months_diff < 0 THEN
        RETURN 'After Start Date';
    ELSIF months_diff = 0 THEN
        RETURN 'Same Month';
    ELSIF months_diff BETWEEN 1 AND 3 THEN
        RETURN '1-3 Months Before';
    ELSIF months_diff BETWEEN 4 AND 6 THEN
        RETURN 'Optimal Window (4-6 Months)';
    ELSE
        RETURN 'Early Filing';
    END IF;
END;
$$ LANGUAGE plpgsql;

